public:
    int maxSumSubmatrix(vector<vector<int>>& matrix, int k) {
        int m = matrix.size();
        int n = matrix[0].size();
        if (m < n) {
            vector<vector<int>> trans(n, vector<int>(m));
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) trans[j][i] = matrix[i][j];
            }
            matrix = move(trans);
            swap(m, n);
        }

        int maxSum = INT_MIN;
        for (int l = 0; l < n; l++) {
            vector<int> rowSums(m, 0);
            for (int r = l; r < n; r++) {
                for (int i = 0; i < m; i++) {
                    rowSums[i] += matrix[i][r];
                }

                int maxSub = INT_MIN, cur = 0;
                for (int x : rowSums) {
                    cur = max(x, cur + x);
                    maxSub = max(maxSub, cur);
                }
                if (maxSub <= k) {
                    maxSum = max(maxSum, maxSub);
                    if (maxSum == k) return k;
                    continue;
                }

                set<int> prefixes = {0};
                int prefix = 0;
                for (int x : rowSums) {
                    prefix += x;
                    auto it = prefixes.lower_bound(prefix - k);
                    if (it != prefixes.end()) {
                        maxSum = max(maxSum, prefix - *it);
                        if (maxSum == k) return k;
                    }
                    prefixes.insert(prefix);
                }
            } 
        }
        return maxSum;
    }
};

class Solution {
    public int maxSumSubmatrix(int[][] matrix, int k) {
        int m = matrix.length;
        int n = matrix[0].length;
        if (m < n) {
            int[][] trans = new int[n][m];
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) trans[j][i] = matrix[i][j];
            }
            matrix = trans;
            int tmp = m; m = n; n = tmp;
        }

        int maxSum = Integer.MIN_VALUE;
        for (int l = 0; l < n; l++) {
            int[] rowSums = new int[m];
            for (int r = l; r < n; r++) {
                for (int i = 0; i < m; i++) {
                    rowSums[i] += matrix[i][r];
                }

                int maxSub = Integer.MIN_VALUE, cur = 0;
                for (int x : rowSums) {
                    cur = Math.max(x, cur + x);
                    maxSub = Math.max(maxSub, cur);
                }
                if (maxSub <= k) {
                    maxSum = Math.max(maxSum, maxSub);
                    if (maxSum == k) return k;
                    continue;
                }

                TreeSet<Integer> prefixes = new TreeSet<>();
                prefixes.add(0);
                int prefix = 0;
                for (int x : rowSums) {
                    prefix += x;
                    Integer target = prefixes.ceiling(prefix - k);
                    if (target != null) {
                        maxSum = Math.max(maxSum, prefix - target);
                        if (maxSum == k) return k;
                    }
                    prefixes.add(prefix);
                }
            }
        }
        return maxSum;
    }
}

var maxSumSubmatrix = function(matrix, k) {
    let m = matrix.length;
    let n = matrix[0].length;
    if (m < n) {
        const trans = Array.from({ length: n }, () => new Array(m).fill(0));
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) trans[j][i] = matrix[i][j];
        }
        matrix = trans;
        const tmp = m; m = n; n = tmp;
    }

    let maxSum = -Infinity;
    for (let l = 0; l < n; l++) {
        const rowSums = new Array(m).fill(0);
        for (let r = l; r < n; r++) {
            for (let i = 0; i < m; i++) {
                rowSums[i] += matrix[i][r];
            }

            let maxSub = -Infinity;
            let cur = 0;
            for (const x of rowSums) {
                cur = Math.max(x, cur + x);
                maxSub = Math.max(maxSub, cur);
            }
            if (maxSub <= k) {
                maxSum = Math.max(maxSum, maxSub);
                if (maxSum === k) return k;
                continue;
            }

            const prefixes = [0];
            let prefix = 0;
            for (const x of rowSums) {
                prefix += x;
                const target = prefix - k;
                let low = 0, high = prefixes.length - 1, ceilIdx = -1;
                while (low <= high) {
                    const mid = (low + high) >> 1;
                    if (prefixes[mid] >= target) {
                        ceilIdx = mid;
                        high = mid - 1;
                    } else {
                        low = mid + 1;
                    }
                }
                if (ceilIdx !== -1) {
                    maxSum = Math.max(maxSum, prefix - prefixes[ceilIdx]);
                    if (maxSum === k) return k;
                }
                let ins = 0;
                while (ins < prefixes.length && prefixes[ins] < prefix) ins++;
                prefixes.splice(ins, 0, prefix);
            }
        }
    }
    return maxSum;
};
